    Bug 2016965 - Add annotations for unsupported tabs API properties. r=kaie


    Add a hint to the documentation, that we do not support these `groupId` and `splitViewId`.

    Differential Revision: https://phabricator.services.mozilla.com/D283443

diff --git a/mail/components/extensions/annotations/tabs.json b/mail/components/extensions/annotations/tabs.json
index 8175f2ed835..c982d266a70 100644
--- a/mail/components/extensions/annotations/tabs.json
+++ b/mail/components/extensions/annotations/tabs.json
@@ -11,6 +11,20 @@
                 "note": "The naming pattern of the built-in cookie stores was deliberately not changed for Thunderbird, but kept for compatibility reasons."
               }
             ]
+          },
+          "groupId": {
+            "annotations": [
+              {
+                "note": "Thunderbird does not support tab groups. This property will always be <code>-1<code> and cannot be changed."
+              }
+            ]
+          },
+          "splitViewId": {
+            "annotations": [
+              {
+                "note": "Thunderbird does not support Split View. This property will always be <code>-1<code> and cannot be changed."
+              }
+            ]
           }
         }
       }
